import { useCallback, useEffect, useState } from 'react';
import confetti from 'canvas-confetti';
import { Check } from 'lucide-react';
import './index.css';
import { articleById } from './data/articles';
import { DEFAULT_FONT, DEFAULT_SAVED, usePersistent, type Subscription, type View } from './lib/store';
import Masthead from './components/Masthead';
import Home from './components/Home';
import CategoryView from './components/CategoryView';
import ArticleView from './components/ArticleView';
import SearchView from './components/SearchView';
import SavedView from './components/SavedView';
import Newsletter from './components/Newsletter';
import Footer from './components/Footer';

/** Permite abrir un artículo compartido con #/articulo/<id>. */
function initialView(): View {
  const m = typeof location !== 'undefined' ? location.hash.match(/^#\/articulo\/([\w-]+)/) : null;
  return m && articleById(m[1]) ? { name: 'articulo', id: m[1] } : { name: 'portada' };
}

export default function App() {
  const [view, setView] = useState<View>(initialView);
  const [saved, setSaved] = usePersistent<string[]>('guardados', DEFAULT_SAVED);
  const [fontSize, setFontSize] = usePersistent<number>('letra', DEFAULT_FONT);
  const [subscription, setSubscription] = usePersistent<Subscription | null>('suscripcion', null);
  const [query, setQuery] = useState('');
  const [toast, setToast] = useState<string | null>(null);

  useEffect(() => { window.scrollTo({ top: 0 }); }, [view]);
  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(() => setToast(null), 2400);
    return () => clearTimeout(t);
  }, [toast]);

  const go = useCallback((v: View) => setView(v), []);
  const open = useCallback((id: string) => setView({ name: 'articulo', id }), []);
  const notify = useCallback((msg: string) => setToast(msg), []);

  const toggleSave = (id: string) => {
    const isSaved = saved.includes(id);
    setSaved(isSaved ? saved.filter((x) => x !== id) : [id, ...saved]);
    notify(isSaved ? 'Quitado de tu lista de lectura' : 'Guardado para leer luego');
  };

  const scrollToNewsletter = () => {
    document.getElementById('newsletter')?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    setTimeout(() => document.getElementById('nl-email')?.focus({ preventScroll: true }), 500);
  };

  const subscribe = (s: Subscription) => {
    setSubscription(s);
    notify('¡Suscripción confirmada!');
    confetti({ particleCount: 70, spread: 70, origin: { y: 0.75 }, colors: ['#E3A13A', '#6A2450', '#FBFAF7'], disableForReducedMotion: true });
  };

  const reset = () => {
    setSaved(DEFAULT_SAVED);
    setFontSize(DEFAULT_FONT);
    setSubscription(null);
    setQuery('');
    setView({ name: 'portada' });
    notify('Datos de ejemplo restablecidos');
  };

  const article = view.name === 'articulo' ? articleById(view.id) : undefined;

  return (
    <div className="sobremesa min-h-screen bg-[#FBFAF7] text-[#221C20]">
      <Masthead view={view} go={go} savedCount={saved.length} onSubscribe={scrollToNewsletter} />

      {view.name === 'portada' && <Home saved={saved} onOpen={open} onToggleSave={toggleSave} go={go} />}
      {view.name === 'categoria' && <CategoryView id={view.id} saved={saved} onOpen={open} onToggleSave={toggleSave} />}
      {view.name === 'articulo' && article && (
        <ArticleView key={article.id} article={article} saved={saved} onToggleSave={toggleSave} onOpen={open} go={go}
          fontSize={fontSize} setFontSize={setFontSize} notify={notify} />
      )}
      {view.name === 'buscar' && <SearchView saved={saved} onOpen={open} onToggleSave={toggleSave} query={query} setQuery={setQuery} />}
      {view.name === 'guardados' && (
        <SavedView saved={saved} onOpen={open} onBrowse={() => go({ name: 'portada' })}
          onRemove={(id) => toggleSave(id)} onClear={() => { setSaved([]); notify('Lista de lectura vaciada'); }} />
      )}

      <Newsletter subscription={subscription} onSubscribe={subscribe}
        onUnsubscribe={() => { setSubscription(null); notify('Te has dado de baja de las cartas'); }} />
      <Footer go={go} onReset={reset} />

      {toast && (
        <div role="status" className="toast-in fixed left-1/2 top-5 z-50 flex items-center gap-2 rounded-full bg-[#221C20] px-5 py-3 text-[14px] text-white shadow-[0_10px_30px_-10px_rgba(34,28,32,.5)]">
          <Check size={16} className="text-[#E3A13A]" /> {toast}
        </div>
      )}
    </div>
  );
}

import clsx from 'clsx';
import { Bookmark } from 'lucide-react';
import { AUTHORS, categoryById, type Article } from '../data/articles';
import { IMG } from '../data/images';
import { formatShortDate, readingMinutes } from '../lib/format';

export type CardProps = {
  article: Article;
  onOpen: (id: string) => void;
  saved: boolean;
  onToggleSave: (id: string) => void;
};

export function SaveButton({ saved, onClick, className }: { saved: boolean; onClick: () => void; className?: string }) {
  return (
    <button
      onClick={onClick}
      aria-pressed={saved}
      aria-label={saved ? 'Quitar de guardados' : 'Guardar para luego'}
      title={saved ? 'Quitar de guardados' : 'Guardar para luego'}
      className={clsx('grid h-9 w-9 shrink-0 place-items-center rounded-full transition-colors',
        saved ? 'text-[#6A2450] hover:bg-[#6A2450]/10' : 'text-[#675F63] hover:bg-[#ECE6DF] hover:text-[#221C20]', className)}
    >
      <Bookmark size={18} strokeWidth={1.8} fill={saved ? 'currentColor' : 'none'} className={saved ? 'pop' : ''} />
    </button>
  );
}

export function Kicker({ article }: { article: Article }) {
  const cat = categoryById(article.category);
  return (
    <span className="text-[13px] font-semibold" style={{ color: cat.color }}>
      {cat.name}
    </span>
  );
}

export function Meta({ article, withAuthor = true }: { article: Article; withAuthor?: boolean }) {
  return (
    <p className="text-[13px] text-[#675F63]">
      {withAuthor && <>{AUTHORS[article.author].name} · </>}
      {formatShortDate(article.date)} · {readingMinutes(article)} min de lectura
    </p>
  );
}

/** Tarjeta vertical para rejillas. */
export default function ArticleCard({ article, onOpen, saved, onToggleSave }: CardProps) {
  return (
    <article className="group flex flex-col">
      <button onClick={() => onOpen(article.id)} className="img-zoom block overflow-hidden rounded-[3px] bg-[#ECE6DF]" tabIndex={-1} aria-hidden>
        <img src={IMG(article.image)} alt={article.imageAlt} loading="lazy" className="aspect-[4/3] w-full object-cover" />
      </button>
      <div className="mt-4 flex items-center justify-between">
        <Kicker article={article} />
        <SaveButton saved={saved} onClick={() => onToggleSave(article.id)} className="-mr-2" />
      </div>
      <h3 className="mt-1">
        <button onClick={() => onOpen(article.id)} className="text-left font-display text-[24px] leading-[1.15] text-[#221C20]">
          <span className="link-title">{article.title}</span>
        </button>
      </h3>
      <p className="mt-2 line-clamp-2 text-[15px] leading-relaxed text-[#4A4246]">{article.dek}</p>
      <div className="mt-3"><Meta article={article} /></div>
    </article>
  );
}

/** Fila compacta con miniatura. */
export function ArticleRow({ article, onOpen, saved, onToggleSave }: CardProps) {
  return (
    <article className="flex gap-4">
      <button onClick={() => onOpen(article.id)} className="img-zoom block h-[84px] w-[104px] shrink-0 overflow-hidden rounded-[3px] bg-[#ECE6DF]" tabIndex={-1} aria-hidden>
        <img src={IMG(article.image)} alt={article.imageAlt} loading="lazy" className="h-full w-full object-cover" />
      </button>
      <div className="min-w-0 flex-1">
        <div className="flex items-start justify-between gap-2">
          <Kicker article={article} />
          <SaveButton saved={saved} onClick={() => onToggleSave(article.id)} className="-mr-2 -mt-2" />
        </div>
        <h3 className="-mt-1">
          <button onClick={() => onOpen(article.id)} className="text-left font-display text-[19px] leading-[1.2] text-[#221C20]">
            <span className="link-title">{article.title}</span>
          </button>
        </h3>
        <p className="mt-1.5 text-[12.5px] text-[#675F63]">{readingMinutes(article)} min de lectura</p>
      </div>
    </article>
  );
}

import { useEffect, useRef, useState } from 'react';
import clsx from 'clsx';
import { ArrowLeft, Bookmark, Link2, Minus, Plus } from 'lucide-react';
import { ARTICLES, AUTHORS, categoryById, type Article } from '../data/articles';
import { IMG } from '../data/images';
import { formatDate, readingMinutes } from '../lib/format';
import type { View } from '../lib/store';
import ArticleCard from './ArticleCard';

const SIZES = [17, 19, 21.5];
const SIZE_NAMES = ['Pequeña', 'Normal', 'Grande'];

type Props = {
  article: Article;
  saved: string[];
  onToggleSave: (id: string) => void;
  onOpen: (id: string) => void;
  go: (v: View) => void;
  fontSize: number;
  setFontSize: (n: number) => void;
  notify: (msg: string) => void;
};

function Block({ text, first }: { text: string; first: boolean }) {
  if (text.startsWith('## ')) return <h2 className="mt-10 font-display text-[1.5em] leading-tight text-[#221C20]">{text.slice(3)}</h2>;
  if (text.startsWith('> '))
    return (
      <blockquote className="my-9 border-l-[3px] border-[#E3A13A] pl-6 font-display text-[1.45em] leading-[1.3] text-[#6A2450]">
        {text.slice(2)}
      </blockquote>
    );
  if (text.startsWith('! '))
    return <aside className="mt-8 rounded-[4px] bg-[#F4EFE8] p-5 text-[0.92em] leading-relaxed text-[#3A3236]">{text.slice(2)}</aside>;
  return <p className={clsx('mt-5', first && 'dropcap')}>{text}</p>;
}

export default function ArticleView({ article, saved, onToggleSave, onOpen, go, fontSize, setFontSize, notify }: Props) {
  const [progress, setProgress] = useState(0);
  const bodyRef = useRef<HTMLDivElement>(null);
  const author = AUTHORS[article.author];
  const cat = categoryById(article.category);
  const isSaved = saved.includes(article.id);
  const minutes = readingMinutes(article);
  const related = ARTICLES.filter((a) => a.id !== article.id)
    .sort((a, b) => Number(b.category === article.category) - Number(a.category === article.category))
    .slice(0, 3);

  useEffect(() => {
    const onScroll = () => {
      const el = bodyRef.current;
      if (!el) return;
      const rect = el.getBoundingClientRect();
      const total = rect.height - window.innerHeight * 0.6;
      setProgress(Math.min(1, Math.max(0, -rect.top / Math.max(total, 1))));
    };
    onScroll();
    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll);
    return () => { window.removeEventListener('scroll', onScroll); window.removeEventListener('resize', onScroll); };
  }, [article.id]);

  const share = async () => {
    const url = `${location.origin}${location.pathname}#/articulo/${article.id}`;
    try { await navigator.clipboard.writeText(url); } catch { /* el portapapeles puede no estar disponible */ }
    notify('Enlace copiado al portapapeles');
  };

  const minutesLeft = Math.max(0, Math.ceil(minutes * (1 - progress)));
  const iconBtn = 'grid h-9 w-9 place-items-center rounded-full text-[#221C20] transition-colors hover:bg-[#ECE6DF] disabled:opacity-35 disabled:hover:bg-transparent';

  return (
    <main>
      <div className="fixed inset-x-0 top-0 z-40 h-[3px] bg-transparent" aria-hidden>
        <div className="h-full origin-left bg-[#E3A13A] transition-transform duration-150" style={{ transform: `scaleX(${progress})` }} />
      </div>

      {/* Barra de lectura */}
      <div className="sticky top-16 z-20 border-b border-[#ECE6DF] bg-[#FBFAF7]">
        <div className="mx-auto flex h-14 max-w-[1200px] items-center justify-between gap-2 px-4 sm:px-6">
          <button onClick={() => go({ name: 'categoria', id: article.category })} className="flex items-center gap-2 text-[14px] text-[#4A4246] hover:text-[#221C20]">
            <ArrowLeft size={17} /> <span>{cat.name}</span>
          </button>
          <p className="hidden text-[13px] text-[#675F63] md:block tabular-nums">
            {progress >= 0.99 ? 'Has terminado el artículo' : `Quedan ${minutesLeft} min de lectura`}
          </p>
          <div className="flex items-center gap-1">
            <div className="flex items-center rounded-full border border-[#ECE6DF]" role="group" aria-label={`Tamaño de letra: ${SIZE_NAMES[fontSize]}`}>
              <button className={iconBtn} disabled={fontSize === 0} onClick={() => setFontSize(fontSize - 1)} aria-label="Reducir tamaño de letra"><Minus size={15} /></button>
              <span className="w-6 text-center font-display text-[17px] leading-none text-[#221C20]" aria-hidden>Aa</span>
              <button className={iconBtn} disabled={fontSize === SIZES.length - 1} onClick={() => setFontSize(fontSize + 1)} aria-label="Aumentar tamaño de letra"><Plus size={15} /></button>
            </div>
            <button onClick={share} className={iconBtn} aria-label="Copiar enlace del artículo" title="Copiar enlace"><Link2 size={17} /></button>
            <button
              onClick={() => onToggleSave(article.id)} aria-pressed={isSaved} aria-label={isSaved ? 'Guardado' : 'Guardar para luego'}
              className={clsx('flex h-9 items-center gap-2 rounded-full px-3 text-[14px] font-semibold transition-colors',
                isSaved ? 'bg-[#6A2450] text-white hover:bg-[#561C41]' : 'bg-[#221C20] text-white hover:bg-[#6A2450]')}
            >
              <Bookmark size={15} fill={isSaved ? 'currentColor' : 'none'} />
              <span className="hidden sm:inline">{isSaved ? 'Guardado' : 'Guardar para luego'}</span>
            </button>
          </div>
        </div>
      </div>

      <article ref={bodyRef} className="pb-16">
        <header className="mx-auto max-w-[760px] px-4 pt-10 text-center sm:px-6 sm:pt-14">
          <button onClick={() => go({ name: 'categoria', id: article.category })} className="text-[14px] font-semibold hover:underline" style={{ color: cat.color }}>
            {cat.name}
          </button>
          <h1 className="mt-4 font-display text-[34px] leading-[1.08] text-[#221C20] sm:text-[50px]">{article.title}</h1>
          <p className="mx-auto mt-5 max-w-[620px] text-[18px] italic leading-relaxed text-[#4A4246] sm:text-[20px]">{article.dek}</p>
          <div className="mt-7 flex items-center justify-center gap-3 text-left">
            <img src={IMG(author.photo)} alt={`Retrato de ${author.name}`} className="h-11 w-11 rounded-full bg-[#ECE6DF] object-cover" />
            <div className="text-[14px] leading-snug">
              <p className="font-semibold text-[#221C20]">{author.name}</p>
              <p className="text-[#675F63]">{formatDate(article.date)} · {minutes} min de lectura</p>
            </div>
          </div>
        </header>

        <figure className="mx-auto mt-10 max-w-[1100px] sm:px-6">
          <div className="bg-[#D9D3C9] sm:rounded-[3px] sm:overflow-hidden">
            <img src={IMG(article.image)} alt={article.imageAlt} className="max-h-[620px] w-full object-cover" />
          </div>
          <figcaption className="mx-auto mt-3 max-w-[680px] px-4 text-[13px] italic text-[#675F63] sm:px-0">{article.caption}</figcaption>
        </figure>

        <div className="mx-auto max-w-[680px] px-4 pt-6 text-[#2C2529] sm:px-6" style={{ fontSize: SIZES[fontSize], lineHeight: 1.72 }}>
          {article.body.map((t, i) => <Block key={i} text={t} first={i === 0} />)}
        </div>

        <footer className="mx-auto mt-12 max-w-[680px] px-4 sm:px-6">
          <div className="flex gap-4 border-y border-[#ECE6DF] py-6">
            <img src={IMG(author.photo)} alt="" loading="lazy" className="h-16 w-16 shrink-0 rounded-full bg-[#ECE6DF] object-cover" />
            <div>
              <p className="text-[15px] font-semibold text-[#221C20]">{author.name} <span className="font-normal italic text-[#675F63]">· {author.role}</span></p>
              <p className="mt-1 text-[15px] leading-relaxed text-[#4A4246]">{author.bio}</p>
            </div>
          </div>
        </footer>
      </article>

      <section className="border-t border-[#ECE6DF] bg-white">
        <div className="mx-auto max-w-[1200px] px-4 py-12 sm:px-6">
          <h2 className="font-display text-[28px] text-[#221C20]">Para seguir leyendo</h2>
          <div className="mt-8 grid gap-x-8 gap-y-10 sm:grid-cols-2 lg:grid-cols-3">
            {related.map((a) => (
              <ArticleCard key={a.id} article={a} saved={saved.includes(a.id)} onOpen={onOpen} onToggleSave={onToggleSave} />
            ))}
          </div>
        </div>
      </section>
    </main>
  );
}

import { useState } from 'react';
import clsx from 'clsx';
import { ARTICLES, categoryById, type CategoryId } from '../data/articles';
import { IMG } from '../data/images';
import { readingMinutes } from '../lib/format';
import ArticleCard, { Meta, SaveButton } from './ArticleCard';

type Sort = 'recientes' | 'leidos' | 'cortos';
const SORTS: { id: Sort; name: string }[] = [
  { id: 'recientes', name: 'Más recientes' },
  { id: 'leidos', name: 'Más leídos' },
  { id: 'cortos', name: 'Lectura corta' },
];

type Props = { id: CategoryId; saved: string[]; onOpen: (id: string) => void; onToggleSave: (id: string) => void };

export default function CategoryView({ id, saved, onOpen, onToggleSave }: Props) {
  const [sort, setSort] = useState<Sort>('recientes');
  const cat = categoryById(id);
  const list = ARTICLES.filter((a) => a.category === id).sort((a, b) =>
    sort === 'leidos' ? b.reads - a.reads : sort === 'cortos' ? readingMinutes(a) - readingMinutes(b) : b.date.localeCompare(a.date));
  const [lead, ...rest] = list;
  const others = ARTICLES.filter((a) => a.category !== id).slice(0, 3);
  const minutes =list.reduce((s, a) => s + readingMinutes(a), 0);

  return (
    <main key={id} className="fade-in">
      <section className="mx-auto max-w-[1200px] px-4 pt-10 sm:px-6 sm:pt-14">
        <div className="flex flex-col gap-6 border-b border-[#221C20]/15 pb-8 md:flex-row md:items-end md:justify-between">
          <div className="max-w-2xl">
            <span className="block h-1.5 w-12 rounded-full" style={{ background: cat.color }} />
            <h1 className="mt-5 font-display text-[48px] leading-none text-[#221C20] sm:text-[64px]">{cat.name}</h1>
            <p className="mt-4 text-[18px] leading-relaxed text-[#4A4246]">{cat.blurb}</p>
            <p className="mt-3 text-[14px] text-[#675F63]">{list.length} artículos · {minutes} minutos de lectura en total</p>
          </div>
          <div className="flex gap-1 rounded-full border border-[#DCD4CB] p-1 self-start md:self-auto" role="tablist" aria-label="Ordenar artículos">
            {SORTS.map((s) => (
              <button key={s.id} role="tab" aria-selected={sort === s.id} onClick={() => setSort(s.id)}
                className={clsx('h-8 rounded-full px-3 text-[13px] transition-colors sm:px-4',
                  sort === s.id ? 'bg-[#221C20] text-white' : 'text-[#4A4246] hover:bg-[#ECE6DF]')}>
                {s.name}
              </button>
            ))}
          </div>
        </div>
      </section>

      {lead && (
        <section className="mx-auto max-w-[1200px] px-4 py-10 sm:px-6">
          <article className="grid items-center gap-8 md:grid-cols-2 md:gap-12">
            <button onClick={() => onOpen(lead.id)} className="img-zoom block overflow-hidden rounded-[3px] bg-[#D9D3C9]" tabIndex={-1} aria-hidden>
              <img src={IMG(lead.image)} alt={lead.imageAlt} className="aspect-[4/3] w-full object-cover" />
            </button>
            <div>
              <h2>
                <button onClick={() => onOpen(lead.id)} className="text-left font-display text-[32px] leading-[1.1] text-[#221C20] sm:text-[40px]">
                  <span className="link-title">{lead.title}</span>
                </button>
              </h2>
              <p className="mt-4 text-[17px] leading-relaxed text-[#4A4246]">{lead.dek}</p>
              <div className="mt-5 flex items-center justify-between gap-3">
                <Meta article={lead} />
                <SaveButton saved={saved.includes(lead.id)} onClick={() => onToggleSave(lead.id)} />
              </div>
            </div>
          </article>
        </section>
      )}

      <section className="mx-auto max-w-[1200px] px-4 pb-16 sm:px-6">
        {[{ title: `Más en ${cat.name}`, items: rest }, { title: 'De otras secciones', items: others }]
          .filter((g) => g.items.length > 0)
          .map((g) => (
            <div key={g.title} className="border-t border-[#ECE6DF] pt-8 pb-6">
              <h2 className="font-display text-[26px] text-[#221C20]">{g.title}</h2>
              <div className="mt-6 grid gap-x-8 gap-y-12 sm:grid-cols-2 lg:grid-cols-3">
                {g.items.map((a) => <ArticleCard key={a.id} article={a} saved={saved.includes(a.id)} onOpen={onOpen} onToggleSave={onToggleSave} />)}
              </div>
            </div>
          ))}
      </section>
    </main>
  );
}

import { useState } from 'react';
import { RotateCcw } from 'lucide-react';
import { CATEGORIES } from '../data/articles';
import type { View } from '../lib/store';

type Props = { go: (v: View) => void; onReset: () => void };

export default function Footer({ go, onReset }: Props) {
  const [confirm, setConfirm] = useState(false);
  return (
    <footer className="bg-[#221C20] text-[#CFC6CA]">
      <div className="mx-auto grid max-w-[1200px] gap-10 px-4 pb-28 pt-12 sm:px-6 md:grid-cols-[1.4fr_1fr_1fr] md:pb-16">
        <div>
          <p className="font-display text-[34px] leading-none text-white">Sobremesa</p>
          <p className="mt-3 max-w-sm text-[14px] leading-relaxed">
            Revista independiente de cocina y viajes. Escribimos despacio, pagamos nuestras cuentas y no publicamos contenido patrocinado.
          </p>
        </div>
        <div>
          <p className="text-[14px] font-semibold text-white">Secciones</p>
          <ul className="mt-3 space-y-2 text-[14px]">
            {CATEGORIES.map((c) => (
              <li key={c.id}><button onClick={() => go({ name: 'categoria', id: c.id })} className="hover:text-white">{c.name}</button></li>
            ))}
          </ul>
        </div>
        <div>
          <p className="text-[14px] font-semibold text-white">Tu lectura</p>
          <ul className="mt-3 space-y-2 text-[14px]">
            <li><button onClick={() => go({ name: 'guardados' })} className="hover:text-white">Artículos guardados</button></li>
            <li><button onClick={() => go({ name: 'buscar' })} className="hover:text-white">Buscar en el archivo</button></li>
            <li>
              {confirm ? (
                <span className="flex flex-wrap items-center gap-2">
                  <span>¿Restablecer guardados, letra y suscripción?</span>
                  <button onClick={() => { onReset(); setConfirm(false); }} className="font-semibold text-[#E3A13A] hover:underline">Sí, restablecer</button>
                  <button onClick={() => setConfirm(false)} className="hover:text-white">Cancelar</button>
                </span>
              ) : (
