import { useState, type FormEvent } from 'react';
import clsx from 'clsx';
import { Check, Mail } from 'lucide-react';
import type { Subscription } from '../lib/store';

const LETTERS = [
  { id: 'domingo', name: 'La carta del domingo', desc: 'Lo mejor de la semana y una receta para el lunes.' },
  { id: 'escapadas', name: 'Escapadas', desc: 'Una ruta para comer bien, cada quince días.' },
];

type Props = {
  subscription: Subscription | null;
  onSubscribe: (s: Subscription) => void;
  onUnsubscribe: () => void;
};

export default function Newsletter({ subscription, onSubscribe, onUnsubscribe }: Props) {
  const [email, setEmail] = useState('');
  const [letters, setLetters] = useState<string[]>(['domingo']);
  const [error, setError] = useState('');

  const submit = (e: FormEvent) => {
    e.preventDefault();
    const value = email.trim();
    if (!value) return setError('Escribe tu correo para recibir la carta.');
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(value)) return setError('Ese correo no parece válido. Revisa que tenga @ y un dominio.');
    if (!letters.length) return setError('Elige al menos una de las dos cartas.');
    setError('');
    onSubscribe({ email: value, letters, since: new Date().toISOString() });
    setEmail('');
  };

  const toggle = (id: string) => setLetters((l) => (l.includes(id) ? l.filter((x) => x !== id) : [...l, id]));

  return (
    <section id="newsletter" className="scroll-mt-20 bg-[#6A2450] text-[#FBF3F7]">
      <div className="mx-auto grid max-w-[1200px] gap-10 px-4 py-14 sm:px-6 md:grid-cols-[1fr_1.1fr] md:py-16">
        <div>
          <Mail size={28} strokeWidth={1.5} className="text-[#E3A13A]" />
          <h2 className="mt-4 font-display text-[34px] leading-[1.1] text-white sm:text-[40px]">Sobremesa en tu correo, sin prisas</h2>
          <p className="mt-4 max-w-md text-[16px] leading-relaxed text-[#EBD7E2]">
            Dos cartas escritas por la redacción, nada de promociones. Más de 38.000 lectores las abren con el primer café del domingo.
          </p>
        </div>

        {subscription ? (
          <div className="fade-in self-center rounded-[4px] bg-white/10 p-6">
            <div className="flex items-center gap-3">
              <span className="grid h-9 w-9 place-items-center rounded-full bg-[#E3A13A] text-[#221C20]"><Check size={18} /></span>
              <p className="font-display text-[22px] text-white">Ya estás en la lista</p>
            </div>
            <p className="mt-3 text-[15px] leading-relaxed text-[#EBD7E2]">
              Recibirás {subscription.letters.map((l) => LETTERS.find((x) => x.id === l)?.name).join(' y ')} en <strong className="text-white">{subscription.email}</strong>.
            </p>
            <button onClick={onUnsubscribe} className="mt-4 text-[14px] text-[#EBD7E2] underline underline-offset-4 hover:text-white">
              Darme de baja
            </button>
          </div>
        ) : (
          <form onSubmit={submit} noValidate className="self-center">
            <div className="grid gap-3 sm:grid-cols-2">
              {LETTERS.map((l) => {
                const on = letters.includes(l.id);
                return (
                  <label key={l.id} className={clsx('flex cursor-pointer gap-3 rounded-[4px] border p-4 transition-colors',
                    on ? 'border-[#E3A13A] bg-white/10' : 'border-white/25 hover:border-white/50')}>
                    <input type="checkbox" checked={on} onChange={() => toggle(l.id)} className="mt-1 h-4 w-4 accent-[#E3A13A]" />
                    <span>
                      <span className="block text-[15px] font-semibold text-white">{l.name}</span>
                      <span className="mt-0.5 block text-[13px] leading-snug text-[#EBD7E2]">{l.desc}</span>
                    </span>
                  </label>
                );
              })}
            </div>
            <div className="mt-4 flex flex-col gap-3 sm:flex-row">
              <label htmlFor="nl-email" className="sr-only">Correo electrónico</label>
              <input
                id="nl-email" type="email" value={email} placeholder="tu@correo.com" autoComplete="email"
                onChange={(e) => { setEmail(e.target.value); if (error) setError(''); }}
                aria-invalid={!!error} aria-describedby={error ? 'nl-error' : undefined}
                className="bare-focus h-12 min-w-0 flex-1 rounded-[3px] border-0 bg-white px-4 text-[16px] text-[#221C20] placeholder:text-[#8B8286] focus:outline-none focus:ring-2 focus:ring-[#E3A13A]"
              />
              <button type="submit" className="h-12 rounded-[3px] bg-[#E3A13A] px-6 text-[15px] font-semibold text-[#221C20] transition-colors hover:bg-[#F0B655]">
                Suscribirme
              </button>
            </div>
            {error && <p id="nl-error" role="alert" className="mt-3 text-[14px] text-[#FFD9A0]">{error}</p>}
            <p className="mt-3 text-[13px] text-[#D9BFCD]">Puedes darte de baja con un clic desde cualquier envío.</p>
          </form>
        )}
      </div>
    </section>
  );
}

