            <X size={20} />
          </button>
        )}
      </div>

      <div className="mt-5 flex flex-wrap items-center gap-2">
        <span className="mr-1 text-[14px] text-[#675F63]">Prueba con</span>
        {SUGGESTIONS.map((s) => (
          <button key={s} onClick={() => setQuery(s)} className="h-8 rounded-full border border-[#DCD4CB] px-3 text-[14px] text-[#4A4246] transition-colors hover:border-[#221C20] hover:text-[#221C20]">
            {s}
          </button>
        ))}
      </div>

      {hasQuery ? (
        <section className="mt-12" aria-live="polite">
          <p className="text-[15px] text-[#675F63]">
            {results.length === 0 ? 'Sin resultados' : `${results.length} ${results.length === 1 ? 'artículo' : 'artículos'}`} para «{debounced.trim()}»
          </p>
          {results.length === 0 ? (
            <div className="mt-6 rounded-[4px] bg-[#F4EFE8] p-8 text-center">
              <p className="font-display text-[24px] text-[#221C20]">No hemos escrito sobre eso… todavía</p>
              <p className="mx-auto mt-2 max-w-md text-[15px] text-[#4A4246]">Revisa la ortografía o prueba con una palabra más general, como «café» o «viaje».</p>
            </div>
          ) : (
            <div className="mt-8 grid gap-x-8 gap-y-12 sm:grid-cols-2 lg:grid-cols-3">
              {results.map((a) => <ArticleCard key={a.id} article={a} saved={saved.includes(a.id)} onOpen={onOpen} onToggleSave={onToggleSave} />)}
            </div>
          )}
        </section>
      ) : (
        <section className="mt-12">
          <h2 className="font-display text-[24px] text-[#221C20]">Publicado recientemente</h2>
          <div className="mt-6 grid gap-x-10 gap-y-7 md:grid-cols-2">
            {recent.map((a) => <ArticleRow key={a.id} article={a} saved={saved.includes(a.id)} onOpen={onOpen} onToggleSave={onToggleSave} />)}
          </div>
        </section>
      )}
    </main>
  );
}

