import type { Article } from '../data/articles';

const fecha = new Intl.DateTimeFormat('es-ES', { day: 'numeric', month: 'long', year: 'numeric' });
const fechaCorta = new Intl.DateTimeFormat('es-ES', { day: 'numeric', month: 'short' });

const toDate = (iso: string) => new Date(iso + 'T12:00:00');

export const formatDate = (iso: string) => fecha.format(toDate(iso));
export const formatShortDate = (iso: string) => fechaCorta.format(toDate(iso)).replace('.', '');

export function readingMinutes(a: Article) {
  const words = a.body.join(' ').split(/\s+/).length + a.dek.split(/\s+/).length;
  return Math.max(2, Math.ceil(words / 180));
}

export const formatReads = (n: number) =>
  n >= 1000 ? `${(n / 1000).toLocaleString('es-ES', { maximumFractionDigits: 1 })} mil lecturas` : `${n} lecturas`;

/** Normaliza para buscar sin tildes ni mayúsculas. */
export const normalize = (s: string) => s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();

export function searchArticles(list: Article[], query: string, authorName: (id: string) => string) {
  const terms = normalize(query).split(/\s+/).filter(Boolean);
  if (!terms.length) return [];
  return list
    .map((a) => {
      const title = normalize(a.title);
      const rest = normalize([a.dek, authorName(a.author), a.category, ...a.body].join(' '));
      let score = 0;
      for (const t of terms) {
        if (title.includes(t)) score += 3;
        else if (rest.includes(t)) score += 1;
        else return { a, score: 0 };
      }
      return { a, score };
    })
    .filter((r) => r.score > 0)
    .sort((x, y) => y.score - x.score)
    .map((r) => r.a);
}

